  function addSwipeNav(el, onSwipeLeft, onSwipeRight){
    let startX = 0, startY = 0, tracking = false;
    el.addEventListener('touchstart', (e) => {
      if(e.touches.length !== 1) return;
      startX = e.touches[0].clientX;
      startY = e.touches[0].clientY;
      tracking = true;
    }, {passive:true});
    el.addEventListener('touchend', (e) => {
      if(!tracking) return;
      tracking = false;
      const dx = e.changedTouches[0].clientX - startX;
      const dy = e.changedTouches[0].clientY - startY;
      if(Math.abs(dx) < 40 || Math.abs(dx) < Math.abs(dy) * 1.5) return; // require a mostly-horizontal, deliberate swipe
      if(dx < 0) onSwipeLeft(); else onSwipeRight();
    }, {passive:true});
  }
  addSwipeNav(document.getElementById('previewPane'), () => goToPage(1), () => goToPage(-1));
  addSwipeNav(document.getElementById('printSinglePage'), () => { currentPrintPage++; renderPrintSinglePage(); }, () => { currentPrintPage--; renderPrintSinglePage(); });

